insert into public.tech_questions (system, q, a, options) values
(1, 'On some Ryanair 737-800s, no taxi light is fitted on the nose landing gear.', 0, '["True", "False"]'::jsonb),
(1, 'What is the minimum distance needed to turn away from an obstacle ahead of the aircraft?', 2, '["9.8m", "12.5m", "7.4m", "5.4m"]'::jsonb),
(1, 'What flight-deck indication appears when a correct emergency access code is entered on the flight-deck door keypad?', 1, '["Amber light illuminates on Flight Deck Emergency Access Panel.", "AUTO UNLK light illuminates", "LOCK light illuminates.", "Single cabin chime is sounded."]'::jsonb),
(1, 'Where is the potable-water quantity indicator located?', 3, '["In the forward galley adjacent to the water heater.", "On the forward Attendant''s panel", "Gauge located in the Water System Service Panel blow the aft right entry door.", "On the aft Attendant''s panel."]'::jsonb),
(1, 'What must be done before discharging a Halon fire extinguisher on the flight deck?', 3, '["The air conditioning re-circulation fans must be switched ON.", "APU must be started and APU bleed air selected on.", "BUS TRANSFER switch ON, ISOLATION valve switch to OPEN, and both pack switches set to HIGH.", "All flight deck crew must don oxygen masks set to 100% emergency oxygen."]'::jsonb),
(1, 'In an emergency, the emergency lights and forward airstairs can be operated from the aft attendant''s panel.', 1, '["True", "False"]'::jsonb),
(1, 'Where is the circuit-breaker panel light control located?', 0, '["Forward overhead panel.", "P6 and P18 panels.", "Captain''s and First Officer''s main panel.", "Aft overhead panel."]'::jsonb),
(1, 'During an evacuation, escape straps can help egress. Which statement is correct for Ryanair escape straps?', 0, '["There are four escape straps fitted - one above the L2 window and one above the R2 window to allow the flight deck crew to egress through the L2 or R2 windows; and one above each of the aft emergency exit door frames, to be attached to the door frame and the wind to aid exiting onto the wing in a ditching situation.", "There are only two escape straps fitted - one above the L2 window and one above the R2 window to allow the flight deck crew to egress through the L2 or R2 windows.", "There are only two escape straps fitted - one above each of the aft emergency exit door frames, to be attached to the door frame and the wing, to aid exiting onto the wing in a ditching situation.", "There are only two escape straps fitted - one above each of the forward emergency exit door frames, to be attached to the door frame and the wing, to aid exiting onto the wing in a ditching situation."]'::jsonb),
(1, 'What is the maximum flight-crew oxygen pressure for the first flight of the day?', 2, '["3000 psi", "1100 psi", "1850 psi", "1000 psi"]'::jsonb),
(1, 'With the PASS OXY switch (aft overhead) selected ON, at what cabin altitude does the passenger oxygen system activate?', 0, '["At altitude selected ON.", "14,000 feet.", "10,000 feet.", "14,000 m."]'::jsonb),
(1, 'Once activated, for how long does the PBE (stowed under the flight-deck left jump seat) supply oxygen?', 2, '["Approximately 6 minutes.", "Approximately 12 minutes.", "Approximately 15-20 minutes", "Provides oxygen continuously until de-activated."]'::jsonb),
(1, 'Operating the airstairs from outside, moving the AIRSTAIRS switch to Extend needs both AC and DC power to extend them.', 0, '["True", "False"]'::jsonb),
(1, 'Before discharging a Halon extinguisher on the flight deck, both recirculation fans must be ON and at least one No 2 flight-deck window unlocked.', 1, '["True", "False"]'::jsonb),
(1, 'What is the correct way to close a No 2 flight-deck window?', 0, '["Pull latch mechanism rod to unlock window.   Move window forward whilst depressing trigger mechanism, turn handle forward and outboard, release trigger to lock.", "Pull lock trigger to unlock window.   Move window forward whilst depressing trigger mechanism, turn handle forward and outboard, release trigger to lock.", "Handle must be in the unlocked position.  Without touching the trigger mechanism, ensure channel is clear and push window forward until trigger lock mechanism engages.", "Handle must be in the locked position. Without touching the trigger mechanism, ensure channel is clear and push window forward until trigger lock mechanism engages."]'::jsonb),
(1, 'What is the wingspan of the Ryanair 737-800 with winglets fitted?', 3, '["Ryanair aircraft are not fitted with Winglets.", "37.57m", "32.18m", "35.79m"]'::jsonb),
(1, 'Can the No 2 flight-deck windows be opened both on the ground and in flight?', 0, '["True", "False"]'::jsonb),
(1, 'How can the emergency exit lights be turned on?', 2, '["If the three position switch located on the FWD Overhead panel is selected to ON.", "Automatically if the three position switch located on the FWD Overhead panel switch is in the ARMED position and electrical power to DC bus No.1 fails or if AC power turned off.", "All answers are correct.", "By lifting the guard and pushing the ON switch located on the Aft Attendant Panel."]'::jsonb),
(1, 'The flight-deck door has a decompression panel that opens automatically on rapid decompression, and an emergency-egress panel the crew can remove by hand to exit if the door jams.', 1, '["True", "False"]'::jsonb),
(1, 'How many oxygen masks does each passenger service unit provide?', 2, '["1", "3", "4", "6"]'::jsonb),
(1, 'Does the aircraft battery need to be ON for STANDBY operation of the forward airstairs from the forward attendant''s panel?', 0, '["True", "False"]'::jsonb),
(1, 'With the EMER EXIT LIGHTS switch in its guarded position, when do the emergency exit lights come on automatically?', 3, '["Whenever the FASTEN SEATBELTS signs are illuminated, with the Flaps beyond Flap 15.", "Immediately.  When guarded the switch is in the ON position", "Never.  When guarded the switch is in the OFF position.", "When DC Bus 1 fails, or AC power is turned off."]'::jsonb),
(1, 'In the lavatories, the water supply can be manually set to feed only the toilet or only the sink taps.', 0, '["True", "False"]'::jsonb),
(1, 'Below which airspeed may the retractable landing lights be extended?', 2, '["There are no retractable landing lights fitted on any Ryanair B737-800.", "At the landing gear extension limit 270 kt.", "Can be extended at ANY speed.", "At the Flap extension limit 250 kt"]'::jsonb),
(1, 'Which statement about the No 2 windows is correct?', 1, '["Both the Captain''s and First Officer''s No 2 Windows can be opened from outside the aircraft.", "The First Officer''s No 2 window can be opened from outside the aircraft.", "The No 2 Windows cannot be opened from outside the aircraft.", "The Captain''s No 2 Window can be opened from outside the aircraft."]'::jsonb),
(1, 'When operating the forward airstairs from the external control, what position must the forward entry door be in?', 3, '["Must be fully closed", "Must be fully open", "Must be partially open", "Can be in any position."]'::jsonb),
(1, 'On the flight-deck door emergency access panel, what does an amber light indicate?', 0, '["Correct access code entered, if in AUTO door will unlock after timer expires.", "Access denied by Flight Deck.", "Incorrect access code entered, after timer expires code can be entered again.", "Electronic door lock inoperative, deadbolt in use."]'::jsonb),
(1, 'How many fire extinguishers are on the flight deck, of what type, and where are they located?', 2, '["1 Halon extinguisher located behind the FO, and 1 CO2 extinguisher located under the second observer''s jump seat.", "1 Halon extinguisher located behind the FO, and 1 Water Glycol extinguisher located under the second observer''s jump seat.", "1 Chemical fire extinguisher, located behind the FO", "2 Halon fire extinguishers, 1 located behind the Captain''s seat and 1 located behind the FO''s seat."]'::jsonb),
(2, 'On standby pack controls, what temperatures do the packs produce?', 1, '["The trim air modulating valves close so no pack air is provided to the two cabin zones, only re-circulated air is provided.", "An average temperature for the two cabin zones.", "The flight deck required temperature will also be provided to the passenger cabin.", "Left pack produces 18 degrees C, right pack produces 22 degrees C."]'::jsonb),
(2, 'Which systems use engine bleed air in operation?', 2, '["Engine and wing anti-icing, engine starting, cabin pressurisation, hydraulic reservoir pressurisation.", "Engine and wing anti-icing, engine starting, air conditioning, cabin pressurisation, hydraulic reservoir pressurisation.", "Engine starting, air conditioning, cabin pressurisation, engine and wing anti-icing, hydraulic, water.", "Engine and wing anti-icing, air conditioning, cabin pressurisation, hydraulic reservoir pressurisation."]'::jsonb),
(2, 'The TRIP RESET switch resets a PACK, WING-BODY OVERHEAT or BLEED TRIP OFF: it isolates the associated valve and clears the alert.', 1, '["True", "False"]'::jsonb),
(2, 'If all zone and primary pack controls fail, how is cabin temperature controlled?', 3, '["The cabin temperatures cannot be controlled in this situation.", "A fixed cabin temperature will be produced in this situation - 24 degrees C from the left pack, and 18 degrees C from the right pack.", "The last settings before the failure will be maintained until the packs are selected OFF.", "The standby pack controls command the packs to produce the average temperature demand of the 2 passenger cabin zones."]'::jsonb),
(2, 'The APU can supply bleed air for two packs on the ground, or one pack in flight.', 0, '["True", "False"]'::jsonb),
(2, 'With all temperature selectors OFF, what fixed temperatures do the pack controls produce?', 1, '["Left Pack, 22 degrees Centigrade.  Right Pack, 20 degrees Centigrade.", "Left Pack, 24 degrees Centigrade.  Right Pack, 18 degrees Centigrade.", "Left Pack, 20 degrees Centigrade.  Right Pack, 22 degrees Centigrade.", "Left Pack, 18 degrees Centigrade.  Right Pack, 24 degrees Centigrade."]'::jsonb),
(2, 'Engine bleed-air pressure is controlled by the bleed air valve, which acts as both a shutoff and a pressure-regulating valve.', 0, '["True", "False"]'::jsonb),
(2, 'What is the main function of the recirculation fans?', 0, '["Reduce engine bleed air demand and load on the packs.", "To provide standby air conditioning if the packs fail.", "Recirculate the air from the passenger cabin the provide heating for the forward cargo compartment", "Recirculate cabin air to allow it to be filtered to remove contaminants as it passes through the recirculation fan HEPA filters."]'::jsonb),
(2, 'Conditioned air from the left pack flows to the flight deck directly from the mix manifold.', 1, '["True", "False"]'::jsonb),
(2, 'The packs produce the coolest temperature selected across the zones, and the other zones are then trimmed to their target with hot trim air.', 0, '["True", "False"]'::jsonb),
(2, 'How many trim-air pressure regulators are in the air-conditioning system?', 2, '["2", "There are no Trim Air Pressure Regulators, only Trim Air Modulating valves.", "1", "3"]'::jsonb),
(2, 'Cabin differential pressure is limited by a pressure-relief system. Which statement is correct?', 1, '["There are two negative pressure relief valves, which limit the cabin pressure to 9.1 psi above ambient.", "There are two pressure relief valves which limit differential pressure to 9.1 psi.", "There is a negative pressure relief valve, which limits the cabin pressure to 9.1 psi above ambient.", "There is an outflow valve which opens when cabin pressure reaches 9.1 psi above ambient."]'::jsonb),
(2, 'What happens if all temperature-zone selectors are set to OFF?', 0, '["Left pack will produce 24 degrees centigrade and right pack will produce 18 degrees centigrade.", "The packs will attempt to maintain an average temperature across all zones.", "The right pack will produce a fixed temperature of 75 degrees Fahrenheit, and the left pack will produce a fixed temperature of 65 degrees Fahrenheit."]'::jsonb),
(2, 'Where are the wing-body overheat sensors located?', 3, '["Engine struts, wing leading edge slats, air conditioning bays, APU duct, keel beam.", "Engine cowling lips, wing leading edge slats, air conditioning bays, APU compartment, keel beam.", "Engine cowl lips, wing leading edge slats, air conditioning bays, electronic equipment bay, APU bleed duct.", "Engine struts, wing inboard leading edges, air conditioning bays, APU bleed duct, keel beam."]'::jsonb),
(2, 'Bleed air is taken from the 4th and 10th stages of the high-pressure compressor.', 1, '["True", "False"]'::jsonb),
(2, 'What happens if one pack fails in flight?', 2, '["The remaining pack when selected to AUTO will be capable of maintaining pressurisation up to aircraft ceiling, only if all Zone Temperature Controllers are selected to OFF.", "The remaining pack will not operate in HIGH flow.", "The remaining pack is capable of maintaining pressurisation and acceptable cabin temperatures up to 41,000 feet.", "The remaining pack will be capable of maintaining pressurisation up to the aircraft maximum certified ceiling, and will attempt to produce an average temperature across all cabin zones."]'::jsonb),
(2, 'What is the function of the dual BLEED light?', 3, '["Illuminates to warn of possible backpressure whenever both engines are providing bleed air, and engines are at different thrust settings.", "Illuminates whenever pressure in APU rises above a pre-set value.", "Illuminates whenever both APU and engines is running to warn of risk of backpressure to APU.", "Illuminates when engine running and APU bleed air valve, engine bleed air valve, and isolation valve are in a position to permit possible backpressure of the APU."]'::jsonb),
(2, 'Which statement is correct?', 1, '["Bleed air is only supplied from the 5th stage when the valve modulates open if bleed air requirement is greater than the 9th stage alone can supply.", "Bleed air is only supplied from the 9th stage when the valve modulates open if bleed air requirement is greater than the 5th stage alone can supply.", "Bleed air is constantly provided from stage 5 and stage 9 of the compressor."]'::jsonb),
(2, 'Cabin pressurisation is controlled by the outflow valve position, though some air is also exhausted through the toilet and galley vents.', 0, '["True", "False"]'::jsonb),
(3, 'The engine cowl anti-ice valve is located upstream of the engine bleed air valve.', 0, '["True", "False"]'::jsonb),
(3, 'If the cowl anti-ice valve fails to reach the position commanded by the ENG ANTI-ICE switch, the COWL VALVE OPEN light stays bright blue and an amber TAI indication appears immediately on the CDS.', 1, '["True", "False"]'::jsonb),
(3, 'What is the effect of selecting the ENG ANTI-ICE switch ON?', 0, '["Stall warning logic adjusts stick shaker and minimum maneuver speed bars on airspeed indicator.", "Adjusted stall warning logic for stick shaker, minimum maneuver speed bars on airspeed indicator, and automatically adjusted FMC displayed VREF; return to normal when engine anti-ice is positioned to OFF.", "Adjusted stall warning logic for stick shaker, minimum maneuver speed bars on airspeed indicator, and automatically adjusted FMC displayed VREF; remain for rest of flight.", "FMC displayed VREF is adjusted automatically."]'::jsonb),
(3, 'On standby power only the Captain''s pitot probe is heated, and if that heating then fails there is no CAPT PITOT alert.', 0, '["True", "False"]'::jsonb),
(3, 'Both on the ground and in flight, the wing anti-ice valves close when the forward thrust levers are advanced above the takeoff warning setting.', 1, '["True", "False"]'::jsonb),
(3, 'The rain-removal system for the forward windows consists of which of the following?', 2, '["Windshield wipers, heated windows, hydroscopic rain repellent coating.", "Windshield wipers.", "Windshield wipers, hydroscopic rain repellent coating.", "Heated windows, Windshield wipers,"]'::jsonb),
(3, 'What do the green ON lights above the window-heat switches indicate?', 0, '["Illuminated means heat being applied to windows, extinguished means windows at correct temperature", "Illuminated means the window Overheat system has activated.", "Extinguished means heat still being applied to window but not yet at correct operating temperature, illuminated means window at correct temperature.", "Illuminated means window heat needs to be switched on for that window, extinguished means heat now being applied to that window."]'::jsonb),
(4, 'In flight below 2000 ft RA on an ILS autopilot approach with flare armed, what happens if you press a TO/GA switch once?', 0, '["Autopilot will disengage, and CWS P will annunciate.", "Autothrottle advances thrust levers to full Go-Around N1.", "Autothrottle advances thrust levers to reduced Go-Around N1.", "Autothrottle will disengage, and ARM is dispalyed in FMA."]'::jsonb),
(4, 'After takeoff, the autothrottle stays in Throttle Hold (THR HLD) until 800 ft RA.', 0, '["True", "False"]'::jsonb),
(4, 'Two seconds after touchdown, the autopilot disengages automatically.', 1, '["True", "False"]'::jsonb),
(4, 'Which components make up the Automatic Flight System (AFS)?', 1, '["Flight directors, MCP mode selector system, autothrottles.", "Autothrottles and autopilot flight director system.", "Autopilot, MCP mode selector system, autothrottles.", "AFDS, MCP mode selector system, autothrottles."]'::jsonb),
(4, 'What normally supplies the N1 limits and target N1 values to the autothrottle?', 1, '["The Autothrottle Computer.", "The Flight Management Computer.", "The Electronic Engine Controls (EECs).", "The Flight Control Computers."]'::jsonb),
(4, 'What does a lit green light in an MCP button mean?', 1, '["That mode is currently de-selected and inactive.", "That switch can be de-selected.", "That mode is currently engaged and active.", "The switch is available to be selected."]'::jsonb),
(4, 'When you engage Level Change (LVL CHG on the MCP) and its green light comes on, what other indications occur as the mode engages?', 3, '["Speed window blanks, MCP SPD annunciated for pitch mode, N1 annunciated for thrust mode.", "Speed window opens to show target speed, MCP SPD annunciated for thrust mode, N1 annunciated for pitch mode.", "Speed window blanks, MCP SPD annunciated for pitch mode, N1 or RETARD/ARM annunciated for thrust mode.", "Speed window opens to show target speed, MCP SPD annunciated for pitch mode, N1 or RETARD/ARM annunciated for thrust mode."]'::jsonb),
(4, 'In flight with the autopilot in CMD B, which FCC controls the flight-director logic on the Captain''s PFD?', 3, '["FMS B", "FCC A", "FMS A", "FCC B"]'::jsonb),
(4, 'During a dual-channel autopilot approach, VOR/LOC must be armed before the second autopilot can be selected.', 1, '["True", "False"]'::jsonb),
(4, 'What does a flashing ''A'' to the left of the selected MCP speed indicate?', 2, '["Overspeeed limiting at Mmo limit", "limiting for maximum speed for current flap setting.", "Underspeed limiting, FMC speed or MCP selected speed cannot be reached.", "Overspeed limititing at Vmo Limit"]'::jsonb),
(4, 'An altitude restriction is entered at top of descent, so the aircraft no longer follows the idle descent path but descends to meet the restriction. After meeting it, which path does the aircraft follow for the rest of the descent?', 1, '["Descends to achieve restriction then descends at 1000 fpm until intercepting original idle descent path. (B)", "Descends to achieve restriction then maintains level flight until intercepts the original idle descent path. (A)", "None of the options", "Descends to achieve restriction, then continues steady descent to End of Descent. (C)"]'::jsonb),
(4, 'In the IAS/MACH display, what does a flashing ''A'' to the left of the figure indicate?', 3, '["Overspeed limiting, current speed selection greater than current flap setting limit.", "Overspeed limiting, Minimum speed for current flap setting cannot be achieved.", "Underspeed limiting, Vmo or Mmo limit.", "Underspeed limiting, FMC or selected speed can not be reached."]'::jsonb),
(4, 'For a dual-autopilot approach, by what altitude must the second autopilot be selected?', 1, '["500 feet RA", "800 feet RA", "1500 feet RA", "350 feet RA"]'::jsonb),
(4, 'The autopilot automatically disengages two seconds after touchdown.', 1, '["True", "False"]'::jsonb),
(4, 'Below what RA should FLARE mode be armed during an autoland?', 2, '["350 feet RA.", "350 feet AGL.", "1500 RA", "50 feet RA."]'::jsonb),
(4, 'An altitude restriction is entered before TOD, so the aircraft starts down early on a new idle path to meet it. If ALT INTV is then selected after the restriction, which path does the aircraft follow?', 1, '["Path A.  Descends to achieve restriction then maintains level flight until intercepts the original idle descent path.", "Path B.  Descends to achieve restriction then descends at 1000 fpm until intercepting original idle descent path.", "Path C.  Descends to achieve restriction, then continues steady descent to End of Descent.", "Path D.  Descends to achieve restriction, then continues on that new idle descent path until new commands are entered."]'::jsonb),
(4, 'With VNAV engaged, what is the effect of pressing SPD INTV?', 1, '["No effect, VNAV remains enagaged with the FMC controlling target speed.", "IAS/MACH window opens up showing current FMC target speed, and IAS/MACH selector can be used to set new desired speed.", "IAS/MACH window blanks and next FMC speed restriction becomes active, magenta target speed displayed above speed tape on PFD.", "Current or next speed restriction deleted from FMC, IAS/MACH window opens up showing previous FMC target speed, and IAS/MACH selector can be used to set new desired speed."]'::jsonb),
(4, 'From where are the N1 limits and target N1 values normally provided to the autothrottle?', 0, '["Flight Management Computer.", "Flight Control Computers.", "Electronic Engine Control Computers.", "Autothrottle Computer."]'::jsonb),
(4, 'At what altitude does the FLARE manoeuvre begin during an autoland?', 3, '["500 feet AGL.", "50 feet AGL.", "350 feet RA.", "50 RA."]'::jsonb),
(4, 'Why do we check that FLARE mode is armed at 500 ft RA?', 0, '["To be aware that A/P will disengage at 350 feet RA if not armed.", "To allow the second A/P to be engaged at this point.", "To allow APP mode to be selected at this point if FLARE not armed.", "To allow start of the flare manoeuvre at 350 feet RA."]'::jsonb),
(4, 'Apart from pressing the N1 switch on the MCP, when else does N1 mode engage automatically?', 3, '["LVL CHG and VNAV engaged within first 2.5 minutes after takeoff.", "Never, N1 mode is only ever manually selected and engaged.", "LVL CHG engaged in climb more than 2.5 minutes after takeoff.", "VNAV engaged in climb and LVL CHG engaged in climb more than 2.5 minutes after takeoff."]'::jsonb),
(4, 'What happens when TO/GA is pressed once on an ILS autopilot approach with FLARE armed?', 3, '["Autothrottle advanced the thrust levers to full Go-Around thrust.", "The autothrottle disengages and THR HLD annunciates in the FMA.", "Autopilot disengages and the Flight Directors re-cycle to give a FD Go-Around.", "Autothrottle advanced the thrust levers to reduced Go-Around N1."]'::jsonb),
(4, 'After takeoff, the autothrottle remains in Throttle Hold (THR HLD) until 800 ft RA.', 0, '["True", "False"]'::jsonb),
(4, 'VOR/LOC must be armed before the second autopilot can be selected on a dual-channel autopilot approach.', 1, '["True", "False"]'::jsonb),
(4, 'Which parts make up the Automatic Flight System (AFS)?', 1, '["Autopilot, Autothrottle, and MCP Mode Selection System.", "Autopilot Flight Director System and Autothrottle.", "Flight Directors, Autothrottle, and MCP Mode Selection System", "Autopilot Flight Director System, Autothrottle and MCP Mode Selector System."]'::jsonb),
(4, 'What causes the autothrottle to disengage?', 0, '["Move A/T ARM switch to OFF, Push Either A/T Disengage switch and An A/T system fault is detected", "Immediately the left main landing gear is compressed, Push Either A/T Disengage switch and Move A/T ARM switch to OFF.", "Push Either A/T Disengage switch and An A/T system fault is detected", "Push Either A/T Disengage switch and Move A/T ARM switch to OFF"]'::jsonb),
(4, 'What are the indications that the autothrottle is disconnected?', 0, '["A/T P/RST disengage light flashes.", "Tone sounds and A/T P/RST disengage light flashes", "Tone sounds and A/T P/RST disengage light illuminates steady", "A/T P/RST disenage light illuminates steady."]'::jsonb),
(4, 'The autothrottle is controlled by FCC A only.', 0, '["True", "False"]'::jsonb),
(4, 'During THR HLD, if you move the thrust levers by hand, the autothrottle tries to return them to their original position.', 1, '["True", "False"]'::jsonb),
(4, 'The autothrottle provides automatic thrust control from the start of takeoff through all phases up to and including landing.', 0, '["True", "False"]'::jsonb),
(4, 'With the autothrottle engaged, what could cause the thrust levers to split (not aligned)?', 3, '["Throttle stagger cannot occur with A/T engaged as both throttle servo motors work identically to position the throttles symetrically.", "One engine A/T suffering a system fault.", "Both EECs in ALTN.", "One EEC in ON, one EEC in ALTN."]'::jsonb),
(5, 'Which microphone options are available to the flight crew?', 0, '["Hand microphone, headset boom microphone, oxygen mask microphone.", "Hand microphone, headset boom microphone, oxygen mask microphone, overhead speaker microphone.", "Headset boom microphone, oxygen mask microphone, ceiling speakers microphone.", "Headset boom microphone and hand microphone."]'::jsonb),
(5, 'What is the result of selecting the ALT-NORM switch on the Audio Control Panel (ACP) to ALT?', 2, '["ACP operates in a degraded mode, VHF-2 for Captain, HF-2 for Observer, and VHF-1 for First Officer.", "All communications are routed through the ACP on the AFT Overhead Panel.", "ACP operates in a degraded mode, VHF-1 for Captain and Observer, VHF-2 for First Officer.", "ACP operates in a degraded mode, VHF-1 for Captain, HF-1 for Observer and VHF-2 for First Officer."]'::jsonb),
(5, 'What is the effect of selecting the cockpit voice recorder ON?', 1, '["Powers the cockpit voice recorder after the first engine is started until 5 minutes after last engine shutdown.", "Powers the cockpit voice recorder until first engine is started, then trips to AUTO.", "Powers the cockpit voice recorder until 5 after the last engine shutdown.", "Powers the cockpit voice recorder until the switch is moved to OFF"]'::jsonb),
(5, 'Upper-fuselage VHF antennas are prone to multipath interference from other traffic, while lower-fuselage antennas are less affected.', 1, '["True", "False"]'::jsonb),
(5, 'Communication between the flight deck and cabin crew is still possible with the SERVICE INTERPHONE switch OFF.', 0, '["True", "False"]'::jsonb),
(5, 'What is the effect of pressing the Pilot Call switch?', 1, '["Two-tone chime in flight deck.", "Single-tone chime in flight deck.", "Single-tone chime in passenger cabin with both pink call lights illuminated.", "Two-tone chime in passenger cabin, with both pink master call lights illuminated."]'::jsonb),
(5, 'Received-communication volume is adjusted by rotating the selected RECEIVER switches on the radio tuning panel.', 1, '["True", "False"]'::jsonb),
(5, 'The flight interphone and service interphone are on separate networks.', 0, '["True", "False"]'::jsonb),
(5, 'What are the three positions of the Audio Control Panel filter switch?', 0, '["V, B, R,   Voice, Both, Range.", "R, G, B,   Radio, Ground, Both.", "V, B, R,    Voice, Both, Radio.", "Pushed to select filtering ON, Pushed again for filtering OFF, rotated to increase or decrease amount of filtering."]'::jsonb),
(6, 'Which of the following is NOT powered by the standby power system?', 0, '["Transformer Rectifier 1.", "Battery Bus.", "AC Standby Bus", "Static Inverter"]'::jsonb),
(6, 'What is the normal power source for the battery bus?', 3, '["The hot battery bus", "the switched hot battery bus", "The battery", "TR3"]'::jsonb),
(6, 'The DC standby bus is powered from the batteries through the static inverter. Select one:', 0, '["False", "True"]'::jsonb),
(6, 'What is the normal voltage of the DC buses?', 3, '["115v", "22-30v", "24v", "28v"]'::jsonb),
(6, 'If all AC generation fails, how long can fully charged batteries supply standby power?', 2, '["Up to 60 minutes.", "Up to 30 minutes.", "A minimum of 60 minutes.", "A minimum of 30 minutes."]'::jsonb),
(6, 'If an IDG fails and the APU cannot power the related transfer bus, what is shed first when an electrical overload is sensed?', 1, '["Automatic load shedding of the galley and main busses on on both Transfer Busses.", "Automatic load shedding of the galleys and main bus on Transfer Bus 2", "Automatic load shedding of the galleys and main bus on Transfer Bus 1.", "Automatic load shedding of the IFE Busses."]'::jsonb),
(6, 'With the BUS TRANSFER switch in AUTO, how do the BTBs operate?', 1, '["BTBs isolate Transfer Bus 1 from Transfer Bus 2, if only 1 IDG is supplying power, DC Cross Tie Relay closes to connect DC Bus 1 to DC Bus 2.", "BTBs automatically maintain power to AC Transfer busses from any operating generator or external power.", "BTBs automatically maintain power to DC Bus 1 and DC Bus 2 through the DC Cross Tie Relay.", "BTBs isolate Transfer Bus 1 from Transfer Bus 2, if only 1 IDG is supplying power, DC Cross Tie Relay opens to isolate DC Bus 1 from DC Bus 2."]'::jsonb),
(6, 'Which bus(es) are shed automatically if the APU is the only electrical source in flight?', 1, '["The galley busses", "All galley and main busses", "The main busses", "Transfer bus 2"]'::jsonb),
(6, 'In flight, what does an illuminated amber TR UNIT light indicate?', 0, '["TR1 has failed, or TR2 and TR3 have failed.", "All three TRs have failed.", "One TR has failed.", "TR1 and TR2 have failed, or TR3 has failed."]'::jsonb),
(6, 'The static inverter converts the battery''s 22 to 30 V DC into a constant 24 V.', 1, '["True", "False"]'::jsonb),
(6, 'Under what conditions are DC bus 1 and DC bus 2 isolated from each other?', 2, '["Switching the Bus Transfer switch to OFF.", "When the cross bus tie relay opens.", "All the other answers are true.", "At glide slope capture during a a flight director or autopilot ILS apporach."]'::jsonb),
(6, 'When external ground power is connected via the external AC receptacle, the GRD POWER AVAILABLE light only illuminates if the supply meets the 115 V AC, 200 Hz, 3-phase quality requirements.', 1, '["True", "False"]'::jsonb),
(6, 'What does an illuminated amber ELEC light on the AC/DC metering panel indicate?', 1, '["A fault exists in the AC power system and the DC power system", "A fault exists in the DC power system or the Standby power system", "A fault exists in the DC power system and the Standby power system", "A fault exists in the AC power system or the DC power system"]'::jsonb),
(6, 'With the STANDBY POWER switch in AUTO, does the loss of a single DC bus trigger automatic switching from normal to alternate power?', 0, '["Only if power from DC Bus 1 is lost", "Only if power from DC Bus 2 is lost", "No, for automatic switching to occur power must be lost from both DC Busses", "Only if power from from DC Bus 1 is lost and power from AC Transfer Bus 1 is also lost"]'::jsonb),
(6, 'Which bus is always connected and powered whenever the aircraft battery is installed?', 1, '["AC standby bus- powered through Transformer Rectifier to ensure no power interuption to GPS system.", "Hot Battery Bus - power immediately available to important systems such as fire extinguishers.", "DC Standby bus - power to important systems that require to be in standby mode.", "Battery bus - power immediately available to important systems such as fire extinguishers."]'::jsonb),
(6, 'Why are the covers on the drive DISCONNECT switches red?', 3, '["For easy identification of an emergency operation in low light conditions.", "To identify an emergency operation control switch.", "To identify a NNP memory item.", "To identify switch action is irreversible in flight."]'::jsonb),
(6, 'If the APU powers transfer bus 1 and GEN 2 powers transfer bus 2, what happens when the GRD PWR switch is turned ON?', 1, '["Ground Power will power Transfer Bus 1 and GEN 2 will power Transfer Bus 2.", "Ground Power will power both Transfer Busses. The SOURCE OFF lights will remain extinguished.", "The APU will power Transfer Bus 1 and Ground Power will power Transfer Bus 2.", "Ground Power will power both Transfer Busses and the SOURCE OFF lights will illuminate."]'::jsonb),
(6, 'What normally powers the DC standby bus?', 1, '["The battery", "TR1, TR2 and TR3", "TR2 and TR3", "DC bus 1 and DC bus 2"]'::jsonb),
(6, 'What is the purpose of the ground service switch on the forward attendant''s panel?', 3, '["Provides power to external services used by ground servicing personnel.", "Energises the No1 and No2 115V GND SERVICE BUS, to allow the galleys water heaters to be powered whilst the aircraft is connected to ground power.", "Powers and sounds external horn through the AC ground services bus to attract attention of ground servicing personnel.", "Provides ground power directly to the AC ground services bus for utility outlets, cabin lighting, and battery charger without powering all aircraft electrical busses."]'::jsonb),
(6, 'What is the normal AC source for TR3?', 0, '["Transfer Bus 2", "Main Bus 1", "Transfer Bus 1", "Main Bus 2"]'::jsonb),
(6, 'What is the effect of selecting a drive disconnect switch to DISCONNECT?', 3, '["AC Standby Bus is immediately powered by Inverter from batteries.", "No effects take place until STANBY POWER switch is also moved to BAT.", "DRIVE light illuminates, AC electrical power is lost on associated Transfer Bus, AC Standby Bus powered from opposite Transfer Bus.", "IDG is disconnected if running, and DRIVE light illuminates."]'::jsonb),
(6, 'If all AC power is lost, what powers the AC standby bus?', 1, '["The TRs", "The Static Inverter", "The DC Standby Bus", "The Battery Charger"]'::jsonb),
(6, 'What powers the main battery charger?', 1, '["AC Ground Service Bus 1", "AC Ground Service Bus 2", "Transfer Bus 2", "Transfer Bus 1"]'::jsonb),
(6, 'The two basic rules of the 737-800 electrical system: only one AC source can be connected at a time, and a second source connecting to a transfer bus automatically disconnects the existing one.', 0, '["True", "False"]'::jsonb),
(6, 'What do you see on the electrical panel when you select GRD PWR ON?', 2, '["GRD POWER light extinguished, SOURCE OFF lights illuminated, GEN OFF BUS lights illuminated, TRANSFER BUS OFF lights extinguished, APU GEN OFF BUS light illuminated.", "GRD POWER AVAILABLE light extinguished, SOURCE OFF lights extinguished, GEN OFF BUS lights illuminated, TRANSFER BUS OFF lights extinguished, APU GEN OFF BUS light illuminated.", "GRD POWER AVAILABLE light illuminated, SOURCE OFF lights extinguished, GEN OFF BUS lights illuminated, TRANSFER BUS OFF lights extinguished, APU GEN OFF BUS light extinguished.", "GRD POWER AVAILABLE light illuminated, SOURCE OFF lights extinguished, GEN OFF BUS lights illuminated, TRANSFER BUS OFF lights extinguished, APU GEN OFF BUS light illuminated."]'::jsonb),
(6, 'On a single IDG with an overload sensed, the system sheds the galleys and main bus from transfer bus 1, then transfer bus 2, then the IFE buses if the overload persists.', 1, '["True", "False"]'::jsonb),
(6, 'On the ground, what does an illuminated TR UNIT light indicate?', 1, '["any two TRs have failed", "any TR has failed", "TR1 has failed or TR2 and TR3 have failed", "All three TRs have failed"]'::jsonb),
(6, 'Under normal conditions, what powers DC bus 1?', 2, '["TR2", "TR1", "TR1 and TR2", "TR2 and TR3"]'::jsonb),
(6, 'Which air-conditioning system will not run unless the CAB/UTIL switch is ON?', 0, '["Left & right Recirculation fans", "Temperature controls", "All 115V AC galley busses", "Air conditioning packs"]'::jsonb),
(6, 'What powers the auxiliary battery charger?', 3, '["Through Ground Service Bus 2", "Through the AC Standby Bus", "Through DC Bus 1", "Through the AC Ground Service Bus"]'::jsonb),
(6, 'With the STANDBY POWER switch in AUTO, does the loss of a single AC transfer bus trigger automatic switching from normal to alternate power?', 3, '["No, for automatic switching to occur power must be lost from both AC Transfer Busses", "Only if power from AC Transfer Bus 1 is lost and power from DC Bus 1 is also lost", "Only if power from AC Transfer Bus 2 is lost", "Only if power from AC Transfer Bus 1 is lost"]'::jsonb),
(6, 'If all engine and APU IDGs are lost, what electrical power does the standby power system provide?', 2, '["22-30V DC", "115V AC and 22 to 30V DC.", "115V AC and 24V DC", "24V DC ."]'::jsonb),
(6, 'Ground power is feeding both transfer buses, the APU is available and is selected to power transfer bus 1. Which statement is correct?', 0, '["Ground power will be automatically disconnected and the APU will power both Transfer Busses.", "Ground power will continue to power the Transfer Busses until the APU is selected to power both Transfer Busses.", "The APU will power Transfer Bus 1 and Ground power will power Transfer Bus 2", "Ground power will be automatically disconnected and the APU will power Transfer Bus 1. Transfer Bus 2 is unpowered."]'::jsonb),
(6, 'What normally powers the AC standby bus?', 3, '["Ground Service Bus 1", "The Static Inverter", "AC Transfer Bus 2", "AC Transfer Bus 1"]'::jsonb),
(6, 'The SOURCE OFF light illuminates whenever an IDG trips offline due to overheating.', 1, '["True", "False"]'::jsonb),
(6, 'Keeping both AC transfer buses continuously powered is primarily the function of what?', 3, '["The Ground Service Busses", "The Transfer Busses", "The IDGs", "The Bus Tie Breakers (BTBs)"]'::jsonb),
(7, 'The APU engine air inlet door is at the rear fuselage, just below and forward of the left horizontal stabiliser.', 1, '["True", "False"]'::jsonb),
(7, 'The APU can run and supply bleed air only, up to the aircraft ceiling of 41,000 ft.', 1, '["True", "False"]'::jsonb),
(7, 'APU cooling air enters with the APU engine air through the APU intake on the right rear fuselage.', 1, '["True", "False"]'::jsonb),
(7, 'In flight with the APU as the only electrical source, if the load exceeds the APU generator''s design limit, the galley and IFE buses are shed first.', 1, '["True", "False"]'::jsonb),
(7, 'The APU needs an AC power supply to start.', 1, '["True", "False"]'::jsonb),
(7, 'With the APU running, how can it be shut down immediately?', 2, '["All of the above.", "Move the APU START switch to OFF.", "Switch the battery off.", "Rotate APU FIRE switch"]'::jsonb),
(7, 'What condition causes an automatic APU shutdown?', 1, '["The APU has no automatic shutdown protection - shutting down the APU is always Flight Crew initiated.", "An APU high oil temperature condition occurs or The APU overspeeds or APU fuel control unit failure.", "An APU high oil temperature condition occurs or The APU overspeeds.", "The APU overspeeds or APU fuel control unit failure"]'::jsonb),
(7, 'With the fuel pumps off, where does the APU get its fuel?', 2, '["Left side of the Fuel Manifold.", "Suction fed from Centre Tank.", "No 1 Main Tank.", "From tapping in left engine supply line."]'::jsonb),
(7, 'Under what normal condition(s) do the EECs select approach idle in flight?', 0, '["Flaps are in landing configuration or engine anti-ice is ON", "Below 15,000 feet", "Landing gear extended", "Below 2,000 feet"]'::jsonb),
(7, 'On a ground start, when does the EEC cut ignition and fuel if a wet start is detected?', 2, '["15 seconds after throttle lever moved to Idle", "10 seconds after start lever moved to idle", "15 seconds after the start lever moved to Idle", "The EEC does not turn off ignition and fuel - this is a crew responsibility."]'::jsonb),
(7, 'What effect does moving the N1 SET outer knob to BOTH have on autothrottle operation?', 3, '["Causes the A/T system to disengage.", "Causes the A/T system to set a reduce Max Thrust bug for both engines.", "Causes the A/T system to set an increased Max Thrust bug for both engines.", "Has no effect on the A/T system operation."]'::jsonb),
(7, 'How is the fuel heated before reaching the engine?', 0, '["The main engine oil cooler and the IDG oil cooler", "The main engine oil cooler.", "The IDG oil cooler", "An electrical fuel heater"]'::jsonb),
(7, 'The MASTER CAUTION and ENG system annunciator lights illuminate if the EEC automatically enters soft alternate mode.', 0, '["True", "False"]'::jsonb),
(7, 'Which indication is NOT sent to the secondary engine indications on the lower DU via the EEC?', 0, '["Oil quantity", "Fuel flow", "Oil temperature", "Oil pressure"]'::jsonb),
(7, 'In flight, if a fault stops the EEC receiving flap or anti-ice signals, at what altitude does the approach-idle schedule begin?', 1, '["Below 20,000 feet.", "Below 15,000 MSL.", "Approach idle must be selected by the crew in these circumstances.", "Below 15,000 feet RA"]'::jsonb),
(7, 'At approximately what point does the engine start valve close and the START VALVE OPEN alert on the upper DU extinguish?', 2, '["20% N1", "50% N2", "56% N2", "25% N2"]'::jsonb),
(7, 'Whereabouts in the engine oil system is the oil filter?', 2, '["In the engine bearings supply line", "In the oil tank", "In the engine oil return line before reaching the oil tank", "In the engine oil supply after leaving the oil tank"]'::jsonb),
(7, 'How is the engine fuel heated before entering the engine?', 3, '["Engine fuel is not heated until it is burnt in the engine combustion chamber.", "Heated only by Kinetic energy imparted due to pressure increase passing through the 1st and 2nd stage engine fuel pumps.", "Heated by passing through engine oil heat exhanger only.", "Heated by passing through IDG oil heat exchanger and engine oil heat exchanger."]'::jsonb),
(7, 'Which bus supplies the left igniter plug?', 0, '["AC Transfer Bus 1", "AC Transfer Bus 2", "The AC Standby Bus", "DC Bus 1"]'::jsonb),
(7, 'Can reverse thrust deploy if the aircraft has not touched down?', 2, '["No, the air/ground safety sensor must be in the ground mode and either radio altimeter senses zero ft RA", "Yes, if the forward thrust levers are in the idle position and both radio altimeters sense less than 10 feet RA.", "Yes, if the forward thrust levers are in the idle position and either radio altimeter senses less than 10 feet RA.", "No, the air/ground safety sensor must be in the ground mode"]'::jsonb),
(7, 'With the start lever at IDLE, which ENGINE START switch position gives ignition to both igniters regardless of the igniter selector position?', 3, '["CONT and FLT", "CONT", "GRD", "FLT"]'::jsonb),
(7, 'During an in-flight start, the EGT start-limit redline is never displayed.', 1, '["True", "False"]'::jsonb),
(7, 'What causes the A/T LIM indication to show white on the upper centre display?', 3, '["The Forward Thrust Levers have been advanced to the fully forward position by the A/T system.", "The Forward Thrust Levers have been manually advanced to the fully forward position.", "The A/T system is no longer sending an EGT limit values to the FMC.", "The FMC is not providing the A/T system with N1 limit values"]'::jsonb),
(7, 'Which bus supplies the right igniter plug?', 3, '["AC Transfer Bus 1", "AC Transfer Bus 2", "DC Bus 1", "The AC Standby Bus"]'::jsonb),
(7, 'How is the EEC affected by the failure of one DEU (Display Electronic Unit)?', 3, '["Both EECs are rendered inoperative and the EEC ON indication extinguishes.", "The EEC for the related side reverts to soft alternate mode and the ALTN switch illuminates.", "Failure of a single DUE has no effect on the EECs.", "Both EECs revert to soft alternate mode and the ALTN switch illuminates."]'::jsonb),
(7, 'At what point in a normal start does the EEC receive electrical power?', 0, '["When the engine start switch is positioned to GRD", "When the engines accelerates to a speed greater than 15% N2", "When the battery switch is placed ON", "When the engines accelerates to a speed greater than 25% N2 or max motoring"]'::jsonb),
(7, 'If both the ON and ALTN lights in the EEC switch are lit, what does that indicate?', 3, '["The soft alternate mode is armed.", "The EEC is inoperative for that engines.", "The EEC has been manually switched to the soft alternate mode", "The EEC has automatically switched to the soft alternate mode."]'::jsonb),
(7, 'After start and reaching stabilised idle (59% N2), a low-oil-pressure condition shows as an amber LOW OIL PRESSURE on the upper DU and the lower-DU oil-press pointer in the amber band.', 1, '["True", "False"]'::jsonb),
(7, 'Raising an engine start lever to IDLE opens which fuel valve(s)?', 1, '["The related engine-mounted fuel shutoff valve and engine bypass valve.", "The related spar fuel shutoff valve and engine-mounted fuel shutoff valve.", "The related engine-mounted fuel shutoff valve.", "The related spar fuel shutoff valve."]'::jsonb),
(7, 'What indicates an impending oil-filter bypass due to contamination?', 2, '["Illumination of the FILTER BYPASS warning light on the Fuel Panel.", "An amber OIL FILTER BYPASS alert illuminates on the upper display unit and illumination of the Master Caution and ENG system annunciator lights.", "An amber OIL FILTER BYPASS alert illuminates on the upper display unit.", "Illumination of the Master Caution and ENG system annunciator lights."]'::jsonb),
(7, 'During a normal reverse sequence, what does an illuminated REVERSER light on the aft overhead panel indicate?', 3, '["The isolation valve has failed to open and the thrust reverser control valve has not moved to the deploy position.", "A normal indication until the reverser sleeves are stowed at the completion of the reverse sequence.", "One or more faults in the system if the light illuminates at the start of the sequence.", "A normal indication if the light extinguishes 10 seconds after the thrust reverser is commanded to stow."]'::jsonb),
(7, 'The 737-800 has no in-flight abnormal-start protection.', 0, '["True", "False"]'::jsonb),
(7, 'When does the OIL FILTER BYPASS alert illuminate on the upper display?', 0, '["Illuminates prior to oil bypassing the scavenge filter.", "If the oil filter bypass has failed in the closed position and oil pressure is beginning to increase.", "Once the oil filter bypass has opened and oil is bypassing the filter.", "Illuminates just prior to oil pump bypass opening as pressure gets near to pressure required to open the bypass."]'::jsonb),
(7, 'Besides the lower-DU indication, engine oil quantity can be checked physically on gauges in the main gear wheel well.', 1, '["True", "False"]'::jsonb),
(7, 'During an in-flight start, when does the EEC cut ignition and fuel if a wet start is detected?', 0, '["No in-flight abnormal start protection.", "15 seconds after start lever moved to Idle.", "As soon as the wet start is detected by the EEC.", "10 seconds after start lever moved to Idle."]'::jsonb),
(7, 'At what rotational speed is the start lever moved to IDLE?', 3, '["Max motoring - 56% N1.", "Starter cutout speed - 56% N2.", "Starter cutout speed - 56% N1.", "Max Motoring - 25% N2."]'::jsonb),
(7, 'When is the EGT start-limit redline displayed?', 2, '["Until the engine achieves self sustaining idle (approx 50%)", "Until starter cutout speed (approx 56%)", "Until the engine achieves stabilised idle (approx 59%)", "The EGT start Limit Redline is only displayed if the EGT exceeds the Start Limit."]'::jsonb),
(7, 'What indicates that the thrust-reverser sleeves have moved from stowed to fully deployed?', 1, '["The reverse thrust lever may be moved beyond the interlock position.", "The REV thrust reverser indication located on the upper display unit illuminates green.", "The REVERSER light on the aft overhead panel illuminates.", "The amber REV thrust reverser indication located on the upper display unit illuminates."]'::jsonb),
(7, 'On the ground with the engine shut down, what does a red box around the N1 RPM digital readout mean?', 3, '["The N1 Limit Bug has been set manually.", "This situation cannot occur - the Red Box only occurs in flight to indicate an operating limit is currently being exceeded.", "The N1 RPM display has suffered a malfunction in flight.", "An inflight exceedance has occurred."]'::jsonb),
(7, 'If the forward thrust lever is brought to idle while the EEC is in soft alternate mode, what is the result?', 0, '["The EEC enters the hard alternate mode, the ALTN switch remains illuminated and the ON indication remains visible.", "Approach idle is commanded by the EEC.", "The EEC will remain in the soft alternate mode, the ALTN switch illuminates and the ON indication remains visible.", "The EEC enters the hard alternate mode, the ALTN switch remains illuminated and the ON indication is blanked."]'::jsonb),
(7, 'With GRD selected and the engine start switch at 1 or 2, how is the crew alerted that the start valve has opened?', 1, '["The blue START VALVE light illuminates bright blue then goes dim blue once the start valve is fully open.", "A START VALVE OPEN alert is displayed on the upper DU.", "The only indication is the N2 gauge increasing to Max Motoring (25%).", "An amber START VALVE OPEN alert is displayed on the lower DU."]'::jsonb),
(8, 'As well as the DISCH switch on the flight-deck fire panel, an APU fire can be put out using the APU ground control panel, in a quick-release access panel immediately forward and below the APU.', 1, '["True", "False"]'::jsonb),
(8, 'How many fire-extinguisher bottles are fitted for the cargo compartments?', 2, '["2 fire extinguisher bottles, one for forward cargo hold, and one for rear cargo hold.", "1 fire extinguisher bottle that can only be discharged into forward cargo hold.", "1 fire extinguisher bottle, that can be selected to be discharged into either cargo hold.", "2 fire extinguisher bottles, 1 rapid discharge bottle and one smaller slow discharge bottle."]'::jsonb),
(8, 'What do the three green lights at the bottom right of the engine fire panel indicate?', 3, '["Fire warning system test 1 completed satisfactorily.", "Fire extinguisher functional test completed satifactorily.", "Fire Switch handles functional test satisfactory.", "Fire extinguisher test continuity normal."]'::jsonb),
(8, 'How can the fire warning bell be silenced?', 1, '["Only by pushing the Master FIRE WARN light", "Pushing Master FIRE WARN light or pushing the BELL CUTOUT switch located on the Overheat/Fire Protection panel.", "The fire warning bell is only silenced once the condition causing the Overheat or Fire warning has been removed.", "Pushing the Master FIRE WARN light, or pushing the bell mute button located next to the speaker on the flight deck ceiling."]'::jsonb),
(8, 'How can you tell whether the lavatory fire extinguisher has discharged?', 0, '["Discharge nozzles changed colour from black to grey and Temperature indicator placard in lavatory changes colour from white to black.", "Steady red light remains illuminated on Lavatory ceiling smoke detector panel after alarm tone has silenced and Lavatory Fire warning illuminated on flight deck.", "Discharge nozzles changed colour from black to grey and Pressure gauge on fire bottle in the red zone.", "Discharge indicator panel above lavatory door illuminated and Temperature indicator placard in lavatory changes colour from white to black."]'::jsonb),
(8, 'The engines and APU have fire-extinguishing systems, while the cargo holds and wheel well have only suppression.', 1, '["True", "False"]'::jsonb),
(8, 'After pressing the DISCH switch, how long until the cargo fire DISCH light shows the cargo fire suppression is fully activated?', 0, '["Up to 30 seconds", "195 minutes.", "Up to 60 seconds.", "Immediately."]'::jsonb),
(8, 'Boeing offers two cargo fire bottles: a rapid-discharge bottle emptied immediately on pressing DISCH, and a slow-discharge bottle released one minute later that discharges over several minutes for a total of 195 minutes of suppression. This slow-discharge bottle is NOT fitted on any Ryanair 737-800.', 0, '["True", "False"]'::jsonb),
(8, 'What is the effect of pulling up the No 1 fire DISCH switch?', 2, '["Closes engine and spar fuel shutoff valves, closes inlet valve to both Air Conditioning Packs, trips IDG control relay, arms both Squibs on both on both engine fire bottles, and allows the DISCH switch to be rotated left or right.", "Closes engine fuel shutoff valve, closes engine bleed air valve, trips IDG control relay, closes hydraulic fluid shutoff valve and isolates EDP low pressure warning light, disables thrust reverser, arms Squib on No1 engine fire bottle, and allows the DISCH switch to be rotated to the left to discharge bottle into N01 engine.", "Closes engine and spar fuel shutoff valves, closes engine bleed air valve, trips IDG control relay, closes hydraulic fluid shutoff valve and isolates EDP low pressure light, disables thrust reverser, arms one Squib on both engine fire bottles, and allows the DISCH switch to be rotated left or right.", "Extinguishes Master Caution and Fire Warning lights, silences Fire Warning Bell, shuts down No1 engine, and discharges No1 Fire Bottle into No1 engine."]'::jsonb),
(8, 'The engines have both overheat and fire warnings, while the APU, cargo holds and wheel well have fire warnings only.', 0, '["True", "False"]'::jsonb),
(8, 'A fault is shown in the left engine overheat/fire detection loops. How would you determine which of the two loops has failed?', 3, '["Move to FAULT/INOP - OVHT/FIRE switch to the central TEST position, then test one loop at a time using the OVHT DET switch selected first to A and then B.", "This indication only occurs when BOTH loops have failed.", "Carry out the test again with the switch selected to FAULT/INOP testing each loop individually with the OVHT DET switch at A then B.", "Carry out the test again one loop at a time using the OVHT DET switch selected to A and then B."]'::jsonb),
(8, 'The engine fire DISCH switches are mechanically locked down and can only be pulled up when an overheat or fire is detected and the switch is illuminated.', 1, '["True", "False"]'::jsonb),
(9, 'The flap slat electronic unit (FSEU) provides flap load relief on all aircraft from Flap 10 through Flap 40.', 1, '["True", "False"]'::jsonb),
(9, 'The yaw damper feeds inputs to the rudder for which purposes, and what effect does it have on the rudder pedals?', 0, '["Provides Gust Dampening, Dutch roll prevention and Turn coordination. The rudder pedals are not displaced by yaw damper operation.", "Provides Gust Dampening and Turn coordination. The rudder pedals move to match rudder movement for feedback to the pilot.", "Provides Gust Dampening and Turn coordination. The rudder pedals are not displaced by yaw damper operation.", "Provides Gust Dampening, Dutch roll prevention and Turn coordination. The rudder pedals are displaced by yaw damper operation to provide feedback to the pilot."]'::jsonb),
(9, 'How does the stall identification system help the pilot recognise and resist moving further into a stall?', 2, '["Elevator Feel Shift Module increase, hydraulic system A pressure to the Elevator Feel and Centering Unit, moving the elevator to provide at least 15 degrees of nose down pitch.", "The yaw damper provides 2 degrees of rudder movement, and the speed trim system automatically pushes the control column forward to warn the pilot that a stall condition was being approached.", "Elevator Feel Shift Module increase, hydraulic system A pressure to the Elevator Feel and Centering Unit, significantly increasing the force required to move the control column rearwards to continue into a stalled condition.", "The elevator feel shift module prevents the yaw damper from making any rudder movement, and the stick shaker activates."]'::jsonb),
(9, 'Moving the flap lever to the FLAP 1 gate drives the leading-edge flaps to what position?', 3, '["Takeoff setting", "Flap 1 position", "Flap 15 position.", "Fully Extended"]'::jsonb),
(9, 'What is the maximum flap-extension altitude?', 0, '["20,000 feet", "41,000 feet", "Field elevation plus 1000 feet.", "2500 feet RA"]'::jsonb),
(9, 'What does an amber FLT CONTROL ''LOW PRESSURE'' light indicate?', 2, '["The STBY RUD system pressure is low.", "Both hydraulic systems pressure to ailerons, elevator and rudder are low.", "Related hydraulic system pressure to ailerons, elevator and rudder is low.", "This light is illuminated whenever the associated FLT CONTROL switch is in the OFF position."]'::jsonb),
(9, 'On later aircraft YW098 to YW164 (short-field performance), the leading-edge slats do not move from extended to fully extended until the flap lever passes the Flap 25 position.', 0, '["True", "False"]'::jsonb),
(9, 'The FSEU closes the trailing-edge bypass valve if it detects trailing-edge flap asymmetry, skew or uncommanded motion, stopping normal flap movement; the flaps can still be driven by electric motors.', 0, '["True", "False"]'::jsonb),
(9, 'What happens to the speedbrakes if the SPEED BRAKE lever is left DOWN during landing?', 1, '["The ground spoilers will deploy on landing if all other conditions are met, but flight spoilers will not deploy.", "The speed brake lever will automatically move to the up position and the spoilers will deploy as normal if all other required conditions are met.", "The spoilers will not deploy regardless of all other required conditions being met.", "The flight spoilers will deploy on landing if all other conditions are met, but ground spoilers will not deploy."]'::jsonb),
(9, 'What does an amber SPEED BRAKE DO NOT ARM light (left forward panel) indicate?', 0, '["Indicates an abnormal condition or test input in the speed brake system and indicates that the wheel speed has dropped below 60 kts on landing and the speedbrake lever has not been moved to the down position.", "Indicates an abnormal condition or test input in the speed brake system.", "Indicates that the wheel speed has dropped below 60 kts on landing and the speedbrake lever has not been moved to the down position.", "The speed brakes must not be extended as airspeed currently too high for safe operation."]'::jsonb),
(9, 'What is the purpose of the ALTERNATE FLAPS master switch, and why is its cover red?', 1, '["Closes the trailing edge flap bypass valve, activates standby pump, and arms ALTERNATE FLAPS position switch.  Red because the action of extending the trailing edge devices cannot be reversed in flight.", "Closes the trailing edge flap bypass valve, activates standby pump, and arms ALTERNATE FLAPS position switch.  Red because the action of extending the leading edge devices cannot be reversed in flight.", "Fully extends the leading edge devices, and can extend and retract the trailing edge flaps. Red because the action cannot be reversed, leading and trailing edge devices cannot be retracted once extended.", "Fully extends the leading and trailing edge flaps. Red because the action cannot be reversed, leading and trailing edge devices cannot be retracted once extended."]'::jsonb),
(9, 'What causes the STBY RUDDER ON light to illuminate?', 1, '["Standby rudder system is commanded on, to pressurise the standby rudder PCU, by selecting YAW DAMPER switch to OFF.", "Standby rudder system is commanded on, either manually or automatically, to pressurise the standby rudder PCU.", "Only illuminated when the standby rudder system has been manually commanded on by selecting a FLT CONTROL switch to STBY RUD - not illuminated when standby rudder system automatically commanded on.", "Only illuminated when the standby rudder system has been automatically commanded on - not illuminated when standby rudder system has been manually commanded on by selecting the FLT CONTROL switch to STBY RUD."]'::jsonb),
(9, 'On landing, when do the ground spoilers deploy?', 1, '["Compression of any landing gear strut.", "Compression of the right main landing gear strut.", "Compression of the nose landing gear.", "Compression of the left main landing gear strut."]'::jsonb),
(10, 'What causes an amber IAS DISAGREE alert at the bottom of the speed tape?', 1, '["V Ref has not been entered", "Captain''s and First Officer''s airspeeds disagree by more than 5 kts for more than 5 seconds.", "Difference of more than 10 kts for more than 10 seconds between Captain''s and First Officer''s airspeed indications.", "Selected V Ref is not correct for current aircraft configuration."]'::jsonb),
(10, 'At the lower end of the speed tape, what does the top of the amber bar indicate?', 2, '["Minimum manoeuvre speed (1.3g manoeuvre capability to stick shaker above approximately 20,000 feet) - (1.3g manoeuvre capability to low speed buffet below approximately 20,000 feet).", "Minimum manoeuvre speed (1.3g manoeuvre capability to stick shaker below approximately 30,000 feet) - (1.3g manoeuvre capability to low speed buffet above approximately 30,000 feet).", "Minimum manoeuvre speed (1.3g manoeuvre capability to stick shaker below approximately 20,000 feet) - (1.3g manoeuvre capability to low speed buffet above approximately 20,000 feet).", "Minimum manoeuvre speed (1.3g manoeuvre capability to stick shaker above approximately 30,000 feet) - (1.3g manoeuvre capability to low speed buffet below approximately 30,000 feet)."]'::jsonb),
(10, 'What does a white CDS MAINT message in the lower-left of the PFD indicate?', 0, '["A dispatchable CDS fault has occurred prior to second engine start.", "A dispatchable CDS fault has occurred prior to first engine start.", "A non-dispatchable CDS fault has occurred post second engine start.", "A non-dispatchable CDS fault has occurred prior to second engine start"]'::jsonb),
(10, 'What does the magenta figure shown above the speed tape mean?', 2, '["Airspeed manually selected in the IAS/MACH window.", "FMC computed airspeed if the IAS/MACH window is blank.", "Airspeed manually selected in the IAS/MACH window and FMC computed airspeed if the IAS/MACH window is blank.", "Current or next speed restriction in the FMC."]'::jsonb),
(10, 'On the PFD, what does the amber ''DISPLAYS CONTROL PANEL'' annunciation indicate?', 2, '["The Display Select Panel on the the side the annunciation is displayed has failed.", "The PFD the annunciation is displayed on has an error and information displayed may be erroneous.", "The EFIS control panel on the side the annunciation is displayed has failed", "The Displays Source Control Panel on the side the annunciation is displayed has failed."]'::jsonb),
(10, 'What does the amber ''INSTR SWITCH'' annunciation indicate?', 1, '["Captain''s and First Officer''s displays are using separate sources of IRU data.", "The IRS switch on the Forward Overhead panel is not selected to NORMAL", "Captain''s and First Officer''s displays are using the same source of IRU data with the IRS switch selected to OFF.", "The IRS switch on the Aft Overhead panel is not selected to NORMAL."]'::jsonb),
(10, 'On the navigation display, how is it presented in VOR, Approach and Plan modes?', 1, '["VOR = true north up, Approach = heading up, Plan = heading up.", "VOR = heading up, Approach = heading up, Plan = true north up.", "VOR = heading up, Approach = true north up, Plan = heading up.", "VOR = true north up, Approach = true north up, Plan = heading up."]'::jsonb),
(10, 'At what stage of flight is the V2+15 bug displayed, and when is it removed?', 2, '["Displayed at takeoff, removed when Pitch Flight director moves to 15 degrees nose up.", "Displayed on Approach, removed once right main landing gear is compressed, throttle levers at Idle, and engines have spooled down from Approach Idle to Ground Idle.", "Displayed at Takeoff, removed at first flap retraction or when Vref entered in CDU.", "Displayed at Approach, removed when flaps at Flap 1 or greater."]'::jsonb),
(11, 'If IRS alignment is lost in flight, navigation mode is inoperative for the rest of the flight.', 0, '["True", "False"]'::jsonb),
(11, 'On later aircraft YW059 through YW164, what default Vertical Required Navigation Performance (VRNP) does the FMC use for oceanic, en-route and terminal phases?', 0, '["400 feet.", "250 feet below, 400 feet above the aircraft planned altitude.", "250 feet.", "400 feet below, 250 feet above the aircraft planned altitude."]'::jsonb),
(11, 'How many ILS receivers are fitted on the Ryanair 737-800?', 3, '["4 receivers.", "1 receiver with 2 seperate channels.", "2 main receivers and a standby single channel receiver.", "2 receivers."]'::jsonb),
(11, 'Where on the FMC CDU are the GPS latitude and longitude shown?', 3, '["NAV DATA", "INIT REF", "POS INIT page 1", "POS REF page 2"]'::jsonb),
(11, 'What colour is the route on the nav display once you activate it with the R6 key?', 0, '["Dashed Cyan", "Dashed Magenta", "White", "Magenta."]'::jsonb),
(11, 'On the aft-overhead IRS panel of later aircraft YW130 through YW164, what are the switch positions clockwise, other than OFF?', 3, '["NAV, ALIGN, ATT.", "ATT, ALIGN, NAV.", "NAV, ALIGN, GLS", "ALIGN, NAV, ATT."]'::jsonb),
(11, 'A single route cannot exceed 99 numbered waypoints.', 1, '["True", "False"]'::jsonb),
(11, 'When an annunciator panel is pushed for a recall, what does an illuminated GPS light indicate?', 0, '["Single GPS sensor unit failure.", "IRS left or right selector switch selected to ATT.", "Failure of both GPS sensor units", "GPS left and right system running in degraded mode."]'::jsonb),
(11, 'On later aircraft YW130 through YW164, the VHF NAV switch changes the data source the DEUs use for the NDs. What data does it transfer?', 0, '["DME, ILS/GLS, VOR, MCP course", "VOR, GBAS, MCP course", "DME, GBAS, VOR, Autothrottle, MCP Course.", "DME, ILS, VOR, MCP course."]'::jsonb),
(11, 'For how long are the navigation databases valid?', 2, '["21 Days", "48 Hours", "28 Days", "Valid until next update"]'::jsonb),
(11, 'Which indications are correct for a single FMC failure (left FMC failed)?', 3, '["FMC CDU FAIL light illuminates, left FMC CDU screen blanks, left ND screen blanks, LNAV diengages with VNAV remaining available.", "FMC P/RST amber light illuminates, A/P P/RST light illuminates, LNAV and VNAV disconnect if engaged, left ND not available.", "FMC P/RST amber light illuminates, normal operation continues with remaining functioning FMC automatically driving both ND screens.", "FMC P/RST amber light illuminates, FAIL light on FMC CDU illuminates, LNAV and VNAV disconnect if engaged, failure information displayed on left ND after delay of 25 to 30 seconds."]'::jsonb),
(11, 'When setting up the FMC, what pre-flight information is required?', 1, '["Initial Position, SID, Route, Performance Data, Takeoff Data.", "Initial Position, Performance Data, Route, Takeoff Data.", "Initial Position, Takeoff and Climb Thrust Limits, Route, Cruise Wind.", "Performance Data, Navigation Database, Route, Takeoff Data."]'::jsonb),
(11, 'What two databases does the FMC use to operate?', 0, '["Navigation and Performance", "Terrain and Airports", "Peformance and Terrain", "Navigation and Airports"]'::jsonb),
(11, 'On the FMC DEP/ARR page, can more than one arrival be entered?', 0, '["True", "False"]'::jsonb),
(11, 'On which FMC page is the IRS position initially set?', 2, '["INIT REF page.", "DEP ARR page.", "POS INIT page", "RTE page."]'::jsonb),
(11, 'On aircraft whose mode selector offers TEST, WX, WX/TURB and MAP, what does selecting WX/TURB display?', 1, '["Weather radar returns, and windshear out to 40 miles.", "Weather radar returns and turbulence within 40 miles.", "Weather radar returns, turbulence out to 40 miles, and windshear out to 20 miles.", "Weather radar returns, and turbulence out to 10 miles whilst on the ground only."]'::jsonb),
(11, 'Whatever range you select on the navigation display, turbulence detection is automatically limited to 40 nm.', 0, '["True", "False"]'::jsonb),
(11, 'In turbulence mode, at what horizontal velocity of precipitation toward or away from the radar does the target turn magenta?', 0, '["5 meters per second or greater.", "2.5 meters per second or greater", "10 meters per second or greater.", "7.5 meters per second or greater"]'::jsonb),
(11, 'What forward arc does the weather-radar antenna sweep?', 3, '["160", "165", "185", "180"]'::jsonb),
(11, 'Some Ryanair 737-800s have a weather radar that can be tilted a selected number of degrees above or below the horizon.', 0, '["True", "False"]'::jsonb),
(11, 'On aircraft with IntuVue weather radar, below what altitude are windshear alerts available?', 2, '["1800 feet RA and below", "2300 feet AGL and below.", "1200 feet RA and below.", "1500 feet AGL and below."]'::jsonb),
(11, 'The IntuVue radar on aircraft YF662 to YF695 and YW001 to YW164 gives clutter-free viewing of significant weather out to what range?', 2, '["220 nautical miles", "120 nautical miles.", "320 nautical miles", "420 nautical miles."]'::jsonb),
(11, 'For the IntuVue radar, in which aircraft conditions does predictive windshear mode turn on automatically?', 3, '["In flight above 1200 feet RA, on ground with throttle levers at takeoff position setting.", "In flight below 1500 feet AGL, on ground with both engines running.", "In flight below 2300 feet AGL, on ground with throttle levers at takeoff position setting.", "In flight below 1800 feet AGL, on ground with throttle levers set for takeoff."]'::jsonb),
(11, 'Some weather radar (WXR) panels have a manual altitude control (ALT); in MAN mode it can be used to do which of the following?', 0, '["Controls weather analysis altitude from 0 - 60,000 MSL in 1000 feet increments", "Controls weather analysis alitude from 500 - 60,000 feet MSL in 100 feet increments", "Controls weather analysis alitude from 0 - 41,000 feet MSL in 100 feet increments", "Manual altitude control is NOT available on any WXR control panels."]'::jsonb),
(11, 'If the aircraft present position cannot be entered on the FMC CDU, it can be entered on the ISDU keyboard.', 0, '["True", "False"]'::jsonb),
(11, 'What is the effect of setting the ADF mode selector to ANT?', 3, '["ADF bearing data sent to Standby Radio Magnetic Indicator as well as the DUs", "ADF bearing data switched to keel antenna only, to minimise multipath interference.", "ADF bearing pointer slews to 135 degrees relative bearing.", "No ADF bearing data available and audio reception optimised."]'::jsonb),
(11, 'On the IRS panel, if the DC FAIL light comes on in flight, all alignment data is lost and the system cannot be reset until the aircraft is parked on the ground.', 1, '["True", "False"]'::jsonb),
(11, 'What colour is the Outer Marker (OM) shown in on the PFD?', 1, '["OM appears in Magenta in top right corner of the Attitude Indicator.", "OM appears Cyan in top right corner of AI.", "OM appears White in top right corner of AI", "OM appears Magenta in lower right corner of Attitude Indicator."]'::jsonb),
(11, 'If IRS alignment is lost in flight, what can be done?', 0, '["The navigation mode remains unavailable for the rest of the flight, but ATT mode can be selected to provide attitude reference.", "The IRS mode selectors must be moved to OFF to allow FMC to hold all GPS and navigation data for remainder of the flight.", "ATT mode can be selected to relevel the system and attain attitude reference, the system can then be returned to ALIGN for the 30 second Fast Align, then returned to NAV once the ALIGN light extinguishes.", "IRS mode selector can be selected to ALIGN for 30 seconds then back to NAV to reset the system."]'::jsonb),
(11, 'Which components make up the Flight Management System?', 1, '["FMCS, A/P, A/T, MCP, EFIS, IRS.", "FMCS, AFDS, A/T, IRS, GPS.", "FMCS, AFDS, MCP, IRS, GPS.", "FMCS, AFDS, A/T, MCP, EFIS, ADIRS."]'::jsonb),
(12, 'With the centre (CTR) tank FUEL PUMP switches ON, an amber LOW PRESSURE light also immediately triggers MASTER CAUTION and a FUEL system annunciator.', 1, '["True", "False"]'::jsonb),
(12, 'For which fuel valves does the flight deck indicate the position to the crew?', 3, '["Centre, No1 and No2 Tanks Fuel Pump Valves, Engine Fuel Shutoff Valve, Cross Feed valve.", "Fuel valves are automatic with no flight deck indications.", "Engine Fuel Shutoff valves, Spar Fuel Shutoff valves, Crossfeed valve, Centre, No1 and No2 tanks Fuel Pump valves.", "Engine Fuel Shutoff valves, Spar Fuel Shutoff valves, Crossfeed valve."]'::jsonb),
(12, 'After the centre tank empties and the auto-shutoff logic stops the pumps, how do the pumps then behave?', 3, '["The pumps will not funtion again until the Centre tank has been refueled above 453 kg.", "There is no shutoff logic, the pumps continue to run with the amber LOW PRESSURE light illuminated until the Flight Crew switch the pumps to OFF.", "The pumps can be activated if necessary by tripping the auto shutoff circuit breaker on Panel P6-1 behind the First Officer.", "Switching the pumps to OFF and then back to ON recycles the auto shutoff logic and the pumps will again activate."]'::jsonb),
(12, 'During a normal start, after the start lever is moved to the IDLE detent, what is the correct SPAR VALVE CLOSED light sequence?', 1, '["Transitions from extinguished, to bright and then dim.", "Transitions from dim, to bright and then extinguishes.", "Transitions from extinguished to bright.", "Transitions from extinguished to dim."]'::jsonb),
(12, 'In flight, a fuel imbalance between the No 1 and No 2 tanks can be corrected by what?', 3, '["Opening the crossfeed valve, turning OFF the fuel pumps for the tank with lower fuel and allowing the pumps from the tank with the higher amount of fuel to transfer fuel to the other tank until the IMBAL amber warning light extinguishes, then close the Crossfeed valve and turn back on the pumps.", "Increase thrust setting on the side with higher amount of fuel and decrease thrust setting on side with lower amount of fuel.", "A Fuel imablance cannot be rectified in flight, as fuel transfer between tanks can only be carried out on the ground using the Ground Refuelling Panel switches.", "Open the Crossfeed cock, turn off the pumps on the low side until the Fuel Quantity Indicators are balanced."]'::jsonb),
(12, 'The fuel imbalance alert is shown only when the aircraft is airborne.', 1, '["True", "False"]'::jsonb),
(12, 'Where is the fuel temperature sensor?', 1, '["1 in the inboard rear of each main tank", "In the No1 main tank.", "In each engine Hydro-Mechanical fuel control unit.", "In each engine supply line adjacent to the Fuel Flow Meter"]'::jsonb),
(12, 'For landing, what is the maximum fuel imbalance between main tanks No 1 and No 2?', 0, '["453 Kgs.", "553 Kgs.", "726 Kgs.", "653 Kgs."]'::jsonb),
(12, 'How many fuel pumps does each tank have, and where are they?', 1, '["The centre tank has 1 AC fuel pump located on the front wall of the centre tank and 1 located on the rear wall of the centre tank.  The No1 main tank has 1 pump located on the rear wall of the No1 tank and 1 pump located on the front wall of the No1 tank .  The No2 tank has 1 pump located on the rear wall of the No2 tank and 1 pump located on the front wall of the No2 tank..", "The centre tank has 2 AC fuel pumps mounted on the rear wall of the centre tank.  The No1 tank has 2 AC pumps mounted in the centre tank - 1 on the front wall and one one the rear wall.  The No2 tank has 2 AC pumps mounted in the centre tank - 1 on the front wall and 1 on the rear wall.  There is also a Jet pump mounted in the centre tank discharging into No1 tank", "The centre tank has 2 AC pumps located on the forward wall of the centre tank.  The No1 main tank has 2 AC pumps located on the rear wall of the No1 tank.  The No2 main tank has 2 AC pumps located on the rear wall of the No2 tank.", "The centre tank has 2 AC pumps located on the forward wall of the centre tank.  The No1 main tank has 1 AC pump located on the rear wall of the No1 tank.  The No2 main tank has 1 AC pump located on the rear wall of the No2 tank."]'::jsonb),
(12, 'What are the usable fuel capacities of the aircraft''s fuel tanks?', 0, '["Centre 13,066kg, No1 = 3,915kg, No2 = 3,915kg.", "Centre = 12,726kg, No1 = 3,453kg, No2 = 3,453kg.", "Centre = 3915kg, No1 = 13,066kg , No2 = 13,066kg", "Centre = 20,025 ltr, No1 = 4,876 ltr, No2 = 4,876 ltr"]'::jsonb),
(12, 'What does a blue light on the Nitrogen Generation System (NGS) mean?', 3, '["Dim blue means NGS valve agrees with commanded position.", "Bright blue means NGS valve closed.", "Bright blue means NGS valve closed or disagrees with commanded position", "NGS system functioning in a degraded condition."]'::jsonb),
(12, 'What drives the spar fuel shutoff valve?', 2, '["AC motor from Standby Bus", "Cables and pulleys", "DC motor from Hot Battery Bus", "Pushrods and cranks"]'::jsonb),
(12, 'With the engines running, the fuel CONFIG alert shows as the No 1 and No 2 fuel quantity indicators turning amber when the centre-tank quantity is above 726 kg and the centre-tank pump switches are off.', 1, '["True", "False"]'::jsonb),
(12, 'In the unlikely event of total generator failure, thrust may deteriorate at high altitude. Why?', 1, '["When on STBY power the fuel pumps run a little slower", "The fuel will be suction fed, which may cause dissolved air released from the fuel to restrict fuel flow in the suction feed line.", "When on STBY power the HMU will be unreliable, therefore thrust deterioration might occur at high altitude", "Loss of AC power will affect the ignition system and therefore create a potential risk of flameout"]'::jsonb),
(12, 'The fuel CONFIG alert (engines running) shows as the No 1 and No 2 fuel quantity indicators turning amber when centre-tank quantity exceeds 726 kg with the centre-tank pump switches off.', 1, '["True", "False"]'::jsonb),
(12, 'In the cruise both centre-tank fuel pumps have failed (both centre LOW PRESSURE lights on). You still have 320 kg in the centre tank and both mains are full. You will see:', 3, '["a LOW indication on the CDS", "a CONFIG indication on the CDS", "a pump LOW PRESSURE indication on the CDS", "There will be no indication on CDS"]'::jsonb),
(12, 'During an engine start, when a start lever is moved to the IDLE detent, which statement is correct?', 3, '["The related SPAR VALVE CLOSED light is unaffected by the engine start lever position.", "The related blue SPAR VALVE CLOSED light transitions from dim to extinguished.", "The related blue SPAR VALVE CLOSED light transitions from extinguished, to bright, and then dim.", "The related blue SPAR VALVE CLOSED light transitions from dim, to bright, and then extinguished."]'::jsonb),
(12, 'The amber fuel IMBAL alert stays displayed until the imbalance is reduced to what?', 1, '["726 kgs", "91 kgs", "453 kgs", "363 kgs"]'::jsonb),
(12, 'With the CROSSFEED selector OPEN but the crossfeed valve closed, what does the VALVE OPEN light show?', 1, '["illuminated dim blue", "illuminated bright blue", "extinguished", "illuminated amber"]'::jsonb),
(12, 'The centre-tank fuel scavenge jet pump operates when what?', 0, '["the No. 1 main fuel tank is about 1/2 full", "the center fuel tank is about 3/4 full", "either engine is operating", "both Center Tank Fuel Pump Switches are turned OFF"]'::jsonb),
(12, 'How many fuel measuring sticks are fitted?', 2, '["6", "20", "16", "12"]'::jsonb),
(12, 'In the cruise both centre-tank fuel pumps have failed. There is still 460 kg in the centre tank and both mains are full. The upper display unit will show:', 3, '["A LOW Alert indication under centre tank.", "A CONFIG Alert indication.", "A pump low pressure indication.", "There will be no indication on the CDS"]'::jsonb),
(12, 'When the engine start lever is placed to CUTOFF, what happens?', 2, '["The engine fuel shutoff valve only closes.", "The spar fuel shutoff valve only closes.", "The spar fuel shutoff valve and engine fuel shutoff valve both close.", "The spar fuel shutoff valve, engine fuel shutoff valve and engine bypass valve all close."]'::jsonb),
(12, 'What is the electrical power source for the engine fuel shutoff valves?', 2, '["the Hot Battery Bus", "the DC Standby Bus", "the Battery Bus", "the AC Standby Bus"]'::jsonb),
(12, 'In flight, both fuel-pump LOW PRESSURE lights for main tank No 1 come on. What happens to the No 1 engine?', 3, '["it continues to operate due to the metering of fuel by the Fuel Control Unit", "it receives fuel from main tank No. 2 automatically", "it will shut down due to fuel starvation", "it receives fuel from main tank No.1 through a suction feed line that bypasses the pumps"]'::jsonb),
(13, 'When are the engine hydraulic pump (ENG 1 and ENG 2) switches turned ON?', 0, '["They de-energize the blocking valve to allow pump pressure to enter the system. The switches should remain ON at shutdown to prolong solenoid life.", "They energize the blocking valve to allow pump pressure to enter the system. The switches should remain ON at shutdown to prolong solenoid life.", "They de-energize the blocking valve to allow pump pressure to enter the system. The switches should remain OFF at shutdown to prolong solenoid life.", "They energize the blocking valve to allow pump pressure to enter the system. The switches should remain OFF at shutdown to prolong solenoid life."]'::jsonb),
(13, 'Which components does hydraulic system A power?', 3, '["Alternate nose wheel steering, Alternate brakes and ground spoilers", "Ground spoilers, trailing edge flaps and the power transfer unit (PTU)", "Ground spoilers, normal nose wheel steering and the Landing Gear Transfer Unit", "Landing gear, normal nose wheel steering and the power transfer unit (PTU)"]'::jsonb),
(13, 'Which statement about thrust-reverser operation is true with hydraulic system A failed?', 2, '["The No.1 thrust reverser will operate normally from System B via the PTU.", "The No.1 thrust reverser will automatically operate using the Standby System.", "The No.1 thrust reverser will operate using the Standby System if the Standby System has been manually or automatically activated.", "The No.1 thrust reverser will be inoperative."]'::jsonb),
(13, 'If the hydraulic system A reservoir leaks, which pump(s) still draw fluid from below the standpipe?', 3, '["Both the the engine driven pump (EDP) and the AC electric motor-driven pump", "Neither pump", "The engine driven pump", "The AC electric motor-driven pump"]'::jsonb),
(13, 'Alternate nose-wheel steering is powered by system A, and normal nose-wheel steering by system B.', 1, '["True", "False"]'::jsonb),
(13, 'Hydraulic system A powers which of the following components?', 2, '["Alternate nose wheel steering, Alternate brakes and ground spoilers", "Alternate nose wheel steering, Alternate brakes and ground spoilers", "None of the other answers are correct", "Ground spoilers, trailing edge flaps and the power transfer unit (PTU)"]'::jsonb),
(13, 'What is the maximum hydraulic system pressure?', 0, '["3,500 psi", "4,500 psi", "4,000 psi", "3,000 psi"]'::jsonb),
(13, 'The Power Transfer Unit (PTU) supplies system A with fluid volume from system B to raise the landing gear at the normal rate when the system A engine-driven pump volume is lost.', 1, '["True", "False"]'::jsonb),
(13, 'Which systems does the hydraulic system power?', 3, '["Flight controls, autothrottles, wheel brakes, leading and trailing edge flaps, leading edge slats, nose wheel steering, landing gear, thrust reversers.", "Yaw damper, autopilot and autothrottle, flight controls, brakes, landing gear, trailing edge flaps and slats, nose wheel steering, tiller, power transfer unit, landing gear transfer unit.", "Flight controls, Anti-skid, trailing edge flaps and slats, nose wheel steering, landing gear, thrust reversers, autopilots.", "Flight controls, wheel brakes, leading and trailing edge flaps, leading edge slats, nose wheel steering, landing gear, thrust reversers, autopilots."]'::jsonb),
(13, 'If hydraulic system A leaks, its engine-driven pump is starved before the electric motor-driven pump; if system B leaks, its electric motor-driven pump is the first to be starved.', 1, '["True", "False"]'::jsonb),
(13, 'The electric motor-driven hydraulic pumps are cooled and lubricated by oil passing through them, then cooled by a fuel-cooled oil cooler in each main tank. What fuel quantity must be in each main tank to run the electric pumps on the ground?', 2, '["453 kg", "363 kg", "760 kg", "726 kg"]'::jsonb),
(13, 'With the engine-driven pumps (EDPs) switched OFF, how is hydraulic pressure kept out of the system?', 3, '["The EDPs are mechanically disengaged from the engine external gearbox by means of a electronic clutch.", "A blocking valve in the pump is de-energised allowing it to close and stop pressure entering the system.", "The EDPs are mechanically disengaged from the engine external gearbox by means of a Sprag clutch.", "A blocking valve in the pump is energised allowing it to close and stop pressure entering the system."]'::jsonb),
(13, 'Moving the STBY RUD switch ON runs the standby pump and opens the standby rudder shutoff valve to pressurise the standby power control unit.', 1, '["True", "False"]'::jsonb),
(13, 'What is the effect on the standby hydraulic system of a leak in system B?', 1, '["No effect as the standby system is supplied from system A.", "No effect as the standby system has its own accumulator.", "The standby system will decrease but only a limited amount due to the standpipe in system B reservoir.", "The level in the standby system will also decrease as it is linked to system B."]'::jsonb),
(13, 'Airborne with flaps retracted, if hydraulic system A or B loses pressure, does the standby hydraulic system activate automatically?', 1, '["Yes, failure of either System A or System B will cause automatic activation of the Standby hydraulic system.", "No, automatic activation only occurs if either System A or System B loose pressure and flaps are extended.", "No, automatic activation only occurs if both System A and System B loose pressure and flaps are extended.", "Yes, but only if both System A and System B loose pressure."]'::jsonb),
(13, 'What effect does a leak in system B downstream of the EDP have on the Power Transfer Unit (PTU)?', 0, '["It will continue to function if required due to oil in the system B reservoir below the standpipe level.", "It will cease to function as it requires oil from system B to operate.", "It will function as normal as it is part of the standby system and powered by system A oil pressure.", "A leak in system B has no effect as the PTU only uses oil from system A to operate."]'::jsonb),
(13, 'With a loss of system B pressure, the standby system can extend the leading and trailing-edge devices; the leading-edge devices cannot be retracted once extended by the standby system, but the trailing-edge flaps can be retracted by electric motors via the ALTERNATE FLAPS switch, with no asymmetry or skew protection.', 1, '["True", "False"]'::jsonb),
(13, 'Which conditions must exist, airborne, for the landing-gear transfer unit to operate?', 0, '["No. 1 engine RPM drops below a limit value, landing gear lever is positioned up, either main landing gear is not up and locked", "No. 1 engine driven pump (EDP) fails, landing gear lever is positioned up, either main landing gear is not up and locked", "No. 1 engine driven pump (EDP) pressure below limits, landing gear lever is positioned up, any main landing gear is not up and locked", "No. 1 engine RPM drops below a limit value, landing gear lever is positioned up, any landing gear is not up and locked"]'::jsonb),
(13, 'If the system B engine-driven pump (EDP) pressure drops below limits, to which flight controls does the PTU supply pressure?', 1, '["Trailing Edge (TE) flaps and Leading Edge (LE) flaps", "The Autoslat system and all leading edge devices", "The landing gear", "Trailing Edge (TE) flaps"]'::jsonb),
(13, 'With hydraulic system A failed and the standby system (single electric motor-driven pump) manually activated, which statement is true?', 0, '["Ground spoiler are inoperative, increasing landing distance. Half of the flight spoilers on each wing are inoperative, reducing roll rate. Engine 1 thrust reverser will deploy and retract at a slower rate and some asymmetry can be anticipated during thrust reverser deployment.", "Ground spoiler are inoperative, increasing landing distance. Half of the flight spoilers on each wing are inop, reducing roll rate. Both thrust reversers are powered by the Standby system to avoid asymmetry during thrust reverser deployment.", "Ground spoiler are inoperative, increasing landing distance. Half of the flight spoilers on each wing are powered by the Standby hydraulic system. Engine 1 thrust reverser will deploy and retract at a slower rate and some asymmetry can be anticipated during thrust reverser deployment.", "Ground spoilers are powered by the Standby system and are operative. Half of the flight spoilers on each wing are inoperative, reducing roll rate. Engine 1 thrust reverser will deploy and retract at a slower rate and some asymmetry can be anticipated during thrust reverser deployment."]'::jsonb),
(13, 'Hydraulic system quantity is shown on the lower DU as a digital 0 to 100% indication.', 1, '["True", "False"]'::jsonb),
(14, 'With RTO selected, the system applies maximum brake pressure automatically when the thrust levers are at idle and speed is at or above 90 kt.', 0, '["True", "False"]'::jsonb),
(14, 'If both normal and alternate brake pressure are lost, can the brakes still stop the aircraft after landing?', 0, '["True", "False"]'::jsonb),
(14, 'Which hydraulic system holds the parking brake?', 0, '["All of the above.", "Hydraulic system A", "Brake accumulator", "Hydraulic system B"]'::jsonb),
(14, 'How far must the emergency gear release handle be pulled before the related gear uplock releases?', 1, '["Approximately 16cm", "Approximately 61cm", "Approximately 6cm.", "Released as soon as handle pulled."]'::jsonb),
(14, 'You select AUTO BRAKE to RTO on the ground and the AUTO BRAKE DISARM light comes on for 2 seconds then goes out. What is the fault?', 1, '["You do not have the parking brake set.", "The system has passed the self test and there is NO fault.", "The Auto Brake has failed the self test and should be re-cycled to off then back to RTO, if the light does not illuminate this time the system is serviceable.", "Autobrake is unavailable."]'::jsonb),
(14, 'Which statement about antiskid protection is false?', 2, '["Antiskid protection is provided for both normal and alternate brake systems.", "All of the above are false.", "Each wheel is provided with individual Antiskid protection in normal and alternate braking", "The Antiskid system provides skid, locked wheel, touchdown and hydroplane protection in both normal and alternate braking."]'::jsonb),
(14, 'The main-panel landing-gear lights are all green, but the aft-overhead panel shows the LEFT gear not down and locked. You can ignore this, since one green light on either panel for each gear means it is down and locked.', 0, '["True", "False"]'::jsonb),
(14, 'Besides moving the autobrake selector to OFF, how else can autobraking be cancelled?', 0, '["Applying manual brakes or Moving Speed Brake lever to DOWN detent.", "Advancing forward thrust levers immediately after touchdown or Applying manual brakes", "Applying manual brakes", "Applying manual brakes, Moving Speed Brake lever to DOWN detent or Advancing forward thrust levers immediately after touchdown."]'::jsonb),
(14, 'Which statement about the nose-wheel steering system is true?', 2, '["If alternate nose wheel steering is activated then the standby hydraulic system operates the nose wheel steering and as well as being in the down position, the nose landing gear must be compressed for nose wheel steering to be available.", "Nose wheel steering is normally powered by hydraulic system A, If alternate nose wheel steering is activated then the standby hydraulic system operates the nose wheel steering and As well as being in the down position, the nose landing gear must be compressed for nose wheel steering to be available.", "Nose wheel steering is normally powered by hydraulic system A and as well as being in the down position, the nose landing gear must be compressed for nose wheel steering to be available.", "If alternate nose wheel steering is activated then the standby hydraulic system operates the nose wheel steering."]'::jsonb),
(14, 'Which statement is true when the landing-gear manual extension access door is open?', 3, '["Normal landing gear extension is possible if Hydraulic system A operational.", "The landing gear cannot be retracted.", "The landing gear can be manually lowered with the lnding gear lever in ANY position.", "All of the above are true"]'::jsonb),
(15, 'Altitude alerting occurs when approaching or leaving the MCP-selected altitude. When is it inhibited?', 0, '["Glide slope is captured, or trailing edge flaps are extended to 25 or greater.", "Leading edge flaps are extended to 25 or greater", "Landing gear is down and locked.", "Leading edge flaps are extended to 25 or greater and the landing gear is extended."]'::jsonb),
(15, 'In flight, the IntuVue radar gives a windshear warning from 0.5 nm to 3 nm ahead of the aircraft.', 1, '["True", "False"]'::jsonb),
(15, 'When carrying out the stall warning test, which statement is correct?', 3, '["The test can be completed once AC power is available", "The test cannot be completed until the DC Busses have been powered for up to 4 minutes.", "The test can be completed on DC power", "The test cannot be completed until the AC Transfer Busses have been powered for up to 4 minutes."]'::jsonb),
(15, 'How can the fire warning bell be silenced on the flight deck?', 2, '["Push the Master Fire Warn lights, press the Horn Cutout of the APU Ground Control Panel.", "Push the master fire warn lights, press the horn cutout of the APU ground control panel, push fire warning bell cutout switch.", "Push the master fire warn lights, push fire warning bell cutout switch.", "Fire bell can only be silenced by pressing either master fire warn light."]'::jsonb),
(15, 'In what colours are the predictive-windshear symbol radials (that help locate a windshear event) displayed?', 0, '["Amber.", "Red and Black banded.", "Displayed amber when a predictive winshear caution is active, and displayed red when a predictive windshear warning is active.", "Red."]'::jsonb),
(15, 'Under which situation does the PSEU light illuminate together with a MASTER CAUTION and an OVERHEAD annunciator?', 2, '["Illuminates as soon as the ground/air system senses ground mode, if an emergency exit flight lock has failed locked or a fault is detected.", "Illuminates 30 seconds after the ground/air system senses air mode, if an emergency exit flight lock has failed locked or a fault is detected.", "Illuminates 30 seconds after the ground/air system senses ground mode, if an emergency exit flight lock has failed locked or a fault is detected.", "Illuminates whenever ground/air system senses air mode, and an emergency exit flight lock has failed locked."]'::jsonb),
(15, 'As well as outputs for all stall warnings, the SMYD computers also provide outputs for GPWS windshear detection and alerting.', 0, '["True", "False"]'::jsonb),
(15, 'When an annunciator panel is pressed, all lights on both panels initially illuminate.', 0, '["True", "False"]'::jsonb),
(15, 'Which systems does the Proximity Switch Electronic Unit (PSEU) monitor?', 0, '["Takeoff/Landing Configuration Warnings, Landing Gear and Air/Ground sensing.", "Air/Ground sensing, Landing Gear and Anti-Skid.", "Takeoff/Landing Configuration Warnings, Landing Gear and Anti-Skid", "Air/Ground sensing, Landing Gear and Air/Ground sensing."]'::jsonb),
(15, 'What does a solid amber circle TCAS symbol indicate?', 0, '["Advises of traffic with potential impact in 40 seconds.", "Advises of traffic with potential impact on 25 seconds.", "Results in aural alert of \"TRAFFIC, TRAFFIC\" when within 6nm with 1200 feet or less of vertical seperation of other traffic.", "Advises that the proximate traffic is descending at more than 500 fpm."]'::jsonb),
(15, 'Which system component determines the stall-warning requirement?', 0, '["Two independent SMYD Computers.", "Two independent ADIRUs.", "A single stall management configuration computer.", "The Captain''s or F/O''s Alpha Vane."]'::jsonb),
(15, 'Which two displays cannot be shown at the same time on the navigation DU?', 2, '["Terrain and TCAS.", "Weather and Data.", "Weather and Terrain.", "TCAS and Airport."]'::jsonb),
(15, 'The stall warning test can only be done on the ground, and the No 1 and No 2 systems must be tested separately to confirm the clacker sounds for each.', 1, '["True", "False"]'::jsonb),
(15, 'Under which circumstances does the GPWS give a ''BANK ANGLE, BANK ANGLE'' aural alert?', 1, '["Whenever the bank angle exceeds the setting on the Bank Angle Selector.", "When roll angle exceeding 35, 40 and 45 degrees.", "Whenever trailing edge flaps are at 1 or greater and roll angle exceeds 35 degrees.", "When roll angle exceeds the maximum of 45 degrees."]'::jsonb),
(15, 'What is significant about the layout of the annunciator panel lights?', 1, '["The lights are arranged in no significant order.", "The lights are arranged to reflect the position of the systems panels on the Overhead Panels.", "The lights are arranged in order of priority to be dealt with in case of multiple system failures.", "The lights on the Captain''s side show the systems that the Captain is responsible for monitoring, and the lights of the F/Os side show the systems the F/O is responsible for monitoring."]'::jsonb),
(15, 'With both engines running and one forward thrust lever below about 20° thrust-lever angle, when can the landing-gear warning horn be silenced with the HORN CUTOUT switch?', 0, '["with flaps UP through 10 if below 800 feet RA and above 200 feet RA", "with flaps UP through 10 if below 800 feet RA and above 300 feet RA", "it cannot be silenced if the thrust lever angle is less than 20 degrees.", "with flaps UP through 25 if below 800 feet RA and above 200 feet RA"]'::jsonb),
(15, 'What is the first radio-altitude callout during the approach?', 3, '["50 feet - \"Fifty\".", "1000 feet - \"One Thousand\".", "2450 feet - \"Twenty Five Hundred\".", "2500 feet  - \"Twenty Five Hundred\"."]'::jsonb),
(15, 'Altitude alerting (a tone and highlighted boxes) occurs a set distance before the selected altitude. How many feet before the selected altitude do the highlighted boxes stop showing?', 1, '["3000 fpm with 3000 feet to go, 2000 fpm with 2000 feet to go, 1000 fpm with 1000 feet to go.", "300 feet", "600 feet", "900 feet"]'::jsonb),
(15, 'Once a deviation alert from the selected altitude has occurred, how is it cancelled?', 0, '["return to within 300 feet of selected altitude or deviate by more than 900 feet from selected altitude, or select a new altitude.", "Press ALT INT to select next FMC target altitude.", "Return to within 200 feet of selected altitude and press the HORN CUTOUT button on the Control Stand.", "Return to within 200 feet of selected altitude."]'::jsonb),
(15, 'The EGPWS holds a terrain database used for look-ahead terrain alerting. Which statement about this terrain database is correct?', 2, '["All EGPWS terrain databases account for man-made obstructions over 100 feet high, in the more detailed areas of the database near major airports.", "All man-made obstructions are accounted for in the detailed areas of the EGPWS terrain database in areas close to major airports.", "Man-made obstructions are not accounted for in all EGPWS terrain databases", "All EGPWS terrain databases account for man-made obstructions over 100 feet high, throughout the whole database area."]'::jsonb),
(15, 'The predictive-windshear aural alerts play through the flight-deck speakers and headsets at a preset volume and cannot be controlled or turned off by the crew.', 0, '["True", "False"]'::jsonb),
(15, 'The PSEU light on the forward overhead panel illuminates on the ground if a PSEU fault is detected, or if an overwing-exit flight lock fails to disengage when commanded.', 1, '["True", "False"]'::jsonb),
(15, 'When does the landing-gear configuration warning horn sound intermittently?', 1, '["Flaps greater than 25, below 800 feet RA, regardless of forward thrust lever position.", "Never", "Flaps up through 10, below 800 feet RA, either forward thrust lever at 20 degrees or less (or less than 34 degrees if only 1 engine running).", "Flaps 1 through 10, below 800 feet RA, either forward thrust lever at 20 degrees or less (or less than 34 degrees if only 1 engine running)."]'::jsonb),
(15, 'At what altitude (in feet) do the radio-altitude callouts begin?', 0, '["TWENTY FIVE HUNDRED.", "ONE THOUSAND.", "TWO THOUSAND", "FIFTEEN HUNDRED."]'::jsonb),
(15, 'The EGPWS shows terrain within 2,500 ft of the aircraft''s barometric altitude on the navigation display.', 1, '["True", "False"]'::jsonb),
(15, 'How is the crew alerted to a deviation from the selected altitude?', 1, '["A warning tone sounds once deviation is 300 feet from selected altitude, the current altitude box turns red and begins to flash.", "A warning tone sounds once deviation is 300 feet from selected altitude, the current altitude box turns amber and begins to flash.", "A warning tone sounds once deviation is 300 feet from selected altitude, the current altitude box begins to flash.", "A warning tone sounds once deviation is 900 feet from selected altitude, the current altitude box turns red and begins to flash."]'::jsonb),
(15, 'TCAS generates a traffic advisory when another aircraft is what distance from the closest point of approach?', 1, '[">6 nm separation with >1200 feet vertical separation.", "40 seconds.", "25 seconds.", "<6 nm separation with < 1200 feet vertical separation."]'::jsonb),
(15, 'At what altitude are TCAS INCREASE DESCENT RAs inhibited?', 2, '["1500 feet AGL", "1,100 feet RA.", "1500 feet RA.", "1,100 feet AGL."]'::jsonb),
(15, 'When configured for landing, the GPWS will NOT alert during an attempted off-airport landing.', 0, '["True", "False"]'::jsonb),
(15, 'How far from projected impact is the ''TERRAIN, TERRAIN, PULL UP'' aural warning given?', 1, '["1.2 nm to 1.5 nm", "20 to 30 seconds.", "1.2nm to 1.5nm or 20 to 30 seconds whichever limit occurs first.", "Whenever descending below unsafe RA while too far from any airport in the terrain database."]'::jsonb),
(15, 'How is the crew warned of exceeding the maximum allowed airspeed?', 1, '["Aural Clacker, speedtape red and black band, stick shaker.", "Aural Clacker, speedtape red and black band.", "Aural Clacker.", "Aural Clacker, speedtape red and black band, speedtape amber band, stick shaker."]'::jsonb),
(15, 'The stall-warning stick shaker is tested with the STALL WARNING TEST buttons on the aft overhead panel: No 1 activates the Captain''s stick shaker and column, No 2 activates the FO''s stick shaker and column.', 1, '["True", "False"]'::jsonb),
(15, 'What is the direct result of low oil pressure in the No 2 IDG?', 0, '["The No2 Drive light illuminates amber.", "No immediate affect noticeable as the Bus Tie Brakers (BTB) automatically connect the No1 IDG to drive both AC Transfer Bus 1 and AC Transfer Bus 2.", "Power is lost on the First Officer''s displays after a delay of 5 minutes.", "Power automatically trips to the STANDBY system."]'::jsonb),
(15, 'Which statement about the CABIN ALTITUDE warning is true?', 3, '["An intermittent warning horn sounds and the amber CABIN ALTITUDE warning lights illuminate when the cabin altitude exceeds 10000 feet", "A steady warning horn sounds and the red CABIN ALTITUDE warning lights illuminate when the cabin altitude exceeds 14000 feet.", "A steady warning horn sounds and the amber CABIN ALTITUDE lights illuminate when the cabin altitude exceeds 14000 feet.", "An intermittent warning horn sounds and the red CABIN ALTITUDE lights illuminate when the cabin altitude exceeds 10000 feet"]'::jsonb),
(15, 'Pressing the ground-proximity BELOW G/S P-INHIBIT light cancels or inhibits the alert when below 1,000 ft RA.', 0, '["True", "False"]'::jsonb),
(15, 'When testing the Mach/airspeed warning system in flight, the No 1 and No 2 systems must be tested separately to confirm the clacker sounds for each independently.', 1, '["True", "False"]'::jsonb);
